+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+        sendButton.setEnabled(true);
+        sendButton.addClickListener(event -> sendMessage());
+
+        nameField.addValueChangeListener(event -> onFieldEdited());
+        emailField.addValueChangeListener(event -> onFieldEdited());
+        phoneField.addValueChangeListener(event -> onFieldEdited());
+        messageField.addValueChangeListener(event -> onFieldEdited());
+
+        VerticalLayout form = new VerticalLayout(nameField, emailField, phoneField, messageField, sendButton);
+        form.setPadding(false);
+        form.setSpacing(true);
+        form.setWidthFull();
+        Shortcuts.addShortcutListener(this, this::sendMessage, Key.ENTER).listenOn(UI.getCurrent());
+
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message");
+        messagesGrid.setWidthFull();
+        messagesGrid.setItems(messageStore.newestFirst());
+
+        add(form, messagesGrid);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog confirmation = new Dialog();
+        confirmation.add("You have unsent changes. Discard them?");
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            confirmation.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            confirmation.close();
+            navigation.proceed();
+        });
+        confirmation.add(keepEditing, discard);
+        confirmation.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+
+    private void onFieldEdited() {
+        if (resettingFields) {
+            return;
+        }
+        if (awaitingEditAfterSend) {
+            awaitingEditAfterSend = false;
+        }
+        sendButton.setEnabled(true);
+    }
+
+    private void sendMessage() {
+        if (!sendButton.isEnabled()) {
+            return;
+        }
+
+        clearValidationErrors();
+
+        String name = nameField.getValue();
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        String message = messageField.getValue();
+
+        boolean valid = true;
+        if (name.isBlank()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            valid = false;
+        }
+
+        if (!email.isBlank() && !EMAIL_PATTERN.matcher(email).matches()) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            valid = false;
+        } else if (email.isBlank() && phone.isBlank()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        if (message.isBlank()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            valid = false;
+        } else if (message.length() > MESSAGE_MAX_LENGTH) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name, email, phone, message));
+        messagesGrid.setItems(messageStore.newestFirst());
+        Notification.show("Message sent");
+
+        resettingFields = true;
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        resettingFields = false;
+        awaitingEditAfterSend = true;
+        sendButton.setEnabled(false);
+    }
+
+    private void clearValidationErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+}
