+package com.example;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @Test
+    void validatesAndSendsMessages() {
+        ContactView view = navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertEquals("Name is required", name.getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertTrue(name.isInvalid());
+        assertTrue(email.isInvalid());
+        assertTrue(message.isInvalid());
+
+        test(name).setValue("Avery");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello");
+        test(send).click();
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertTrue(email.isInvalid());
+
+        test(email).clear();
+        test(phone).setValue("555-0100");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertTrue(message.isInvalid());
+
+        test(message).setValue("Hello");
+        test(send).click();
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+        assertTrue($(Notification.class).exists());
+        assertTrue(test($(Notification.class).first()).getText().contains("Message sent"));
+
+        Grid<?> grid = $(Grid.class).single();
+        assertEquals(1, test(grid).size());
+        assertEquals("Avery", test(grid).getCellText(0, 0));
+        assertEquals("Hello", test(grid).getCellText(0, 1));
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        assertEquals(1, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void protectsTypedFormUntilDiscarded() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        test(name).setValue("Unsaved");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(test(dialog).isOpen());
+        assertFalse($(com.vaadin.flow.component.html.H1.class).withText("About").exists());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertFalse(test(dialog).isOpen());
+        assertEquals("Unsaved", name.getValue());
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+        assertTrue($(com.vaadin.flow.component.html.H1.class).withText("About").exists());
+    }
+
+    @Test
+    void enterSendsAndTheNextEditEnablesSendAgain() {
+        navigate(ContactView.class);
+        test($(TextField.class).withLabel("Name").single()).setValue("Jordan");
+        test($(EmailField.class).withLabel("Email").single()).setValue("jordan@example.com");
+        test($(TextArea.class).withLabel("Message").single()).setValue("Hi");
+
+        fireShortcut(com.vaadin.flow.component.Key.ENTER);
+
+        Button send = $(Button.class).withText("Send").single();
+        assertFalse(send.isEnabled());
+        test($(TextField.class).withLabel("Name").single()).setValue("J");
+        assertTrue(send.isEnabled());
+    }
